/** Generated by scaffold-auth-pages. */
import { createSlice } from '@reduxjs/toolkit';
import { loginThunk, signupThunk, fetchMeThunk } from '~/services/httpServices/authService';
import type { AuthState } from '~/types/auth';

// Field names match the AuthState contract in ~/types/auth (emitted by
// scaffold-api-client-types): isAuthenticated / isLoading / authChecked /
// error. v99b evidence: LLM-emitted guards + pages read these names, so
// the slice has to write them. Prior `loading` field name created a
// silent contract mismatch — pages compiled (they used inline interface
// definitions) but state was always `undefined` at runtime.
const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  isLoading: false,
  authChecked: false,
  error: null,
};

export const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    clearAuth: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.error = null;
      state.isLoading = false;
    },
    clearAuthError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(loginThunk.pending, (s) => { s.isLoading = true; s.error = null; })
      .addCase(loginThunk.fulfilled, (s, a) => {
        s.isLoading = false;
        s.user = a.payload.user ?? null;
        s.isAuthenticated = true;
      })
      .addCase(loginThunk.rejected, (s, a) => { s.isLoading = false; s.error = a.error.message ?? 'Login failed'; })
      .addCase(signupThunk.pending, (s) => { s.isLoading = true; s.error = null; })
      .addCase(signupThunk.fulfilled, (s, a) => {
        s.isLoading = false;
        s.user = a.payload.user ?? null;
        s.isAuthenticated = true;
      })
      .addCase(signupThunk.rejected, (s, a) => { s.isLoading = false; s.error = a.error.message ?? 'Signup failed'; })
      .addCase(fetchMeThunk.pending, (s) => { s.isLoading = true; })
      .addCase(fetchMeThunk.fulfilled, (s, a) => {
        s.isLoading = false;
        s.user = a.payload;
        s.isAuthenticated = !!a.payload;
        s.authChecked = true;
      })
      .addCase(fetchMeThunk.rejected, (s) => {
        s.isLoading = false;
        s.user = null;
        s.isAuthenticated = false;
        s.authChecked = true;
      });
  },
});

export const { clearAuth, clearAuthError } = authSlice.actions;
export default authSlice.reducer;
